manifest.harness_source:
"""One authorized T022 matrix. Operator-selected answers only; no automatic retries."""
import asyncio, base64, hashlib, json, os, secrets, shutil, subprocess, tempfile, time
from datetime import datetime, timezone
from pathlib import Path
from uuid import uuid4
import httpx
from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse, HTMLResponse, Response
from meta_vibe_coding import agents, evaluation
from meta_vibe_coding.core import FlowError
from meta_vibe_coding.process import CliFailure
from meta_vibe_coding.settings import Limits

ROOT=Path('/tmp/mvc-comparison-v2')
REPO=Path('/Users/honghuy127/GitHub/meta-vibe-coding')
NATIVE=agents.run_cli

def utc(): return datetime.now(timezone.utc).isoformat()
def sha(raw): return hashlib.sha256(raw).hexdigest()
def record_streams(out,err,status):
    result={'returncode':status}
    for name,raw in [('stdout',out),('stderr',err)]:
        result[name+'_sha256']=sha(raw)
        try:result[name]=raw.decode('utf-8')
        except UnicodeError:
            result[name]=raw.decode('utf-8',errors='replace')
            result[name+'_base64']=base64.b64encode(raw).decode('ascii')
    return result
def exclusive(path, value):
    with os.fdopen(os.open(path, os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600),'w') as f:
        json.dump(value,f,ensure_ascii=False,indent=2);f.write('\n');f.flush();os.fsync(f.fileno())

class Harness:
    def __init__(self):
        self.plan=json.loads((REPO/'artifacts/l0-comparison-plan-v2.json').read_text())
        self.cases=json.loads((REPO/self.plan['frozen_cases']['path']).read_text())
        self.matrix=[(r['case_id'],a) for r in self.plan['matrix'] for a in r['approaches']]
        self.jobs={};self.active=None;self.reservations=0;self.gate=asyncio.Lock()
        evaluation.verify_checkout(REPO)
        snapshot=evaluation.source_snapshot(REPO)
        self.source={'source_snapshot':snapshot,'source_hashes':{p:sha(c.encode()) for p,c in snapshot.items()},'plan_sha256':sha((REPO/'artifacts/l0-comparison-plan-v2.json').read_bytes()),'plan_snapshot':self.plan}
        self.token=secrets.token_hex(24)
        self.log=None

    def event(self, kind, **data):
        self.log.write(json.dumps({'type':kind,'at_utc':utc(),**data},ensure_ascii=False)+'\n')
        self.log.flush();os.fsync(self.log.fileno())

    def verify(self):
        evaluation.verify_checkout(REPO)
        if agents.PROMPT!=self.plan['frozen_runtime']['wrapper_prompt']: raise ValueError('Imported prompt differs')
        if json.loads(agents.SCHEMA)!=self.plan['native_output']['wrapper']: raise ValueError('Imported wrapper schema differs')
        if evaluation.native_schema(evaluation.BaselineResponse)!=self.plan['native_output']['baseline']: raise ValueError('Imported baseline schema differs')
        if evaluation.source_snapshot(REPO)!=self.plan['frozen_runtime']['source_snapshot']: raise ValueError('Runtime source changed')
        if sha((REPO/'artifacts/l0-comparison-plan-v2.json').read_bytes())!=self.source['plan_sha256']: raise ValueError('Plan changed')
        if sha((REPO/self.plan['frozen_cases']['path']).read_bytes())!=self.plan['frozen_cases']['sha256']: raise ValueError('Cases changed')
        if sha((REPO/'requirements.lock').read_bytes())!=self.plan['frozen_runtime']['requirements_lock_sha256']: raise ValueError('Dependency lock changed')

    def start(self):
        self.verify()
        exclusive(ROOT/'run.claim',{'native_invocation_limit':98,'matrix':self.matrix,
            'authority':'Owner requested steps1 through3 and continued; fresh v2 cap98, saved login, no purchases/fallback/retries.'})
        exclusive(ROOT/'control.json',{'token':self.token})
        self.log=os.fdopen(os.open(ROOT/'journal.jsonl',os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600),'w')
        env=agents.agent_environment('codex')
        version=subprocess.run(['codex','--version'],env=env,check=True,capture_output=True,text=True).stdout.strip()
        login=subprocess.run(['codex','login','status'],env=env,check=True,capture_output=True,text=True)
        login_text=login.stdout+login.stderr
        if 'Logged in using ChatGPT' not in login_text: raise RuntimeError('Saved ChatGPT login required.')
        self.version=version
        manifest={'kind':'fictional-regression-matrix','started_at_utc':utc(),
            'authority':{'user_instruction':'Do 1 to 3, one by one; continue' ,'native_invocation_limit':98,
                'additional_spending_usd':0,'saved_login_status':'Logged in using ChatGPT',
                'api_key_environment_forwarded':False,'purchases':False,'fallback':False,'automatic_retries':False},
            'source':self.source,'prelive_review':json.loads((ROOT/'prelive-review.json').read_text()),'harness_source':Path(__file__).read_text(),
            'harness_sha256':sha(Path(__file__).read_bytes()),
            'offline_harness_checks_source':(ROOT/'check_harness.py').read_text(),
            'offline_harness_checks':json.loads((ROOT/'harness-checks.json').read_text()),'agent_version':version,
            'agent_binary_sha256':sha(Path(shutil.which('codex')).resolve().read_bytes()),
            'requested_model':'gpt-6-luna','reported_model':None,
            'operational_details':{'input_bytes_including_trusted_prompt':32000,'stdout_bytes':1000000,
                'stderr_bytes':128000,'session_seconds':1800,'request_seconds':300,'calls_per_job':7,
                'questions_per_job':5,'matrix_order':self.matrix,'one_attempt_per_job':True,
                'variations_share_base_limits':True,'baseline_uses_Candidate_or_adopt':False},
            'notes':['Version2 plan records a fresh98-call allowance; cases and outputs previously exposed, regression only.',
                'Questions and responsive fact selections are manually recorded by the coordinator; operator is not blinded.',
                'Both approaches use the same native process boundary; capture preserves bounded stdout/stderr/exit status, including partial timeout output.',
                'No claims of OS isolation, provider retention, billing reconciliation, stochastic stability or owner comprehension.']}
        exclusive(ROOT/'manifest.json',manifest)
        self.event('run_started',manifest_sha256=sha((ROOT/'manifest.json').read_bytes()))

    def select(self, case_id, approach):
        if self.active and not self.active['closed']: raise ValueError('Finish the active first attempt.')
        index=len(self.jobs)
        if index>=len(self.matrix) or self.matrix[index]!=(case_id,approach): raise ValueError('Preserve frozen matrix order.')
        case=next(c for c in self.cases['cases'] if c['id']==case_id)
        jid=case_id+'-'+approach
        exclusive(ROOT/(jid+'.claim'),{'job':jid,'started_at_utc':utc(),'attempt':1,'max_calls':7})
        job={'id':jid,'case_id':case_id,'approach':approach,'calls':0,'questions':0,
            'started_at':time.time(),'closed':False,'state':None,'previous':None,'baseline':None,
            'conversation':[{'role':'owner','text':case['initial_request']}],'failure':None,'phases':[],
            'case':case}
        if approach=='wrapper':
            job['agent']=agents.CodingAgent(limits=Limits(300,1800));job['agent'].version=self.version
        self.jobs[jid]=job;self.active=job
        self.event('job_started',job=jid,initial_request=case['initial_request'],attempt=1)
        return self.summary(job)

    async def native(self,args,**kwargs):
        # Product help probes do not consume inference. Version was checked before freezing.
        if '--help' in args or '--version' in args: return await NATIVE(args,**kwargs)
        self.verify();job=self.active
        if not job or job['closed'] or job['calls']>=7 or self.reservations>=98:
            raise FlowError('limit','The authorized first-attempt allowance is exhausted.')
        if time.time()-job['started_at']>=1800: raise FlowError('limit','Case deadline exhausted.')
        if len(kwargs['content'].encode())+len((agents.PROMPT if job['approach']=='wrapper' else self.plan['baseline_prompt']).encode())>32000:
            raise FlowError('limit','Input exceeds the shared 32000-byte limit.')
        kwargs['timeout']=min(kwargs['timeout'],1800-(time.time()-job['started_at']))
        schema_path=Path(args[args.index('--output-schema')+1])
        if schema_path.is_symlink() or schema_path.resolve().parent!=Path(kwargs['cwd']).resolve():
            raise ValueError('Schema input must belong to request workspace')
        schema_content=schema_path.read_bytes()
        if schema_path.stat().st_mode & 0o777!=0o600: raise ValueError('Schema input must be private')
        if json.loads(schema_content)!=self.plan['native_output'][job['approach']]: raise ValueError('Schema input differs from plan')
        if schema_content.decode() not in kwargs['content']: raise ValueError('Schema input differs from stdin')
        schema_input={'path':schema_path.name,'sha256':sha(schema_content),'content':schema_content.decode(),'kind':'wrapper-owned input'}
        job['calls']+=1;self.reservations+=1;number=self.reservations;began=time.perf_counter()
        self.event('native_started',job=job['id'],number=number,job_call=job['calls'],argv=['codex',*args[1:]],
            stdin=kwargs['content'],stdin_sha256=sha(kwargs['content'].encode()),timeout_seconds=kwargs['timeout'],schema_input=schema_input)
        streams={}
        def capture(out,err,status): streams.update(record_streams(out,err,status))
        error=None
        try:
            return await NATIVE(args,**kwargs,capture=capture)
        except Exception as exc:
            error={'type':type(exc).__name__,'code':getattr(exc,'code',None)}
            raise
        finally:
            self.event('native_finished',job=job['id'],number=number,elapsed_seconds=time.perf_counter()-began,
                error=error,streams=streams,wrapper_input_files=[schema_path.name],unexpected_workspace_files=[str(p.relative_to(kwargs['cwd']))
                    for p in Path(kwargs['cwd']).rglob('*') if p.is_file() and p!=schema_path])

    @staticmethod
    def summary(job):
        if job['approach']=='wrapper':
            s=job['state'];a=s.get('assessment') if s else None
            active=next((q for q in reversed(s['questions']) if not q['retired'] and not q['answer_turn_id']),None) if s else None
            return {'job':job['id'],'calls':job['calls'],'questions_counted':job['questions'],'closed':job['closed'],
                'failure':job['failure'],'question':active,'assessment':a,'facts':s['facts'] if s else {}}
        return {'job':job['id'],'calls':job['calls'],'questions_counted':job['questions'],'closed':job['closed'],
            'failure':job['failure'],'response':job['baseline']}

    async def post_product(self,path,payload):
        async with httpx.AsyncClient(transport=httpx.ASGITransport(app=self.product),base_url='http://localhost') as client:
            result=await client.post(path,json=payload,headers={'x-control':self.token})
        body=result.json();self.event('http',job=self.active['id'],path=path,request=payload,status=result.status_code,response=body)
        return result.status_code,body

    async def step(self,body):
        job=self.active
        if not job or job['closed'] or job['failure']: raise ValueError('No active healthy first attempt.')
        if set(body)-{'question_count','fact_topics','variation','unknown','provisional','rationale','as_answer'}:
            raise ValueError('Unknown operator action fields.')
        count=body.get('question_count',0)
        if type(count) is not int or count<0: raise ValueError('Count separate information requests.')
        topics=body.get('fact_topics',[]);variation=body.get('variation');unknown=body.get('unknown',False)
        provisional=body.get('provisional',False)
        state=job['state'];last=job['baseline']
        outstanding=(next((q for q in reversed(state['questions']) if not q['retired'] and not q['answer_turn_id']),None)
            if job['approach']=='wrapper' and state else last.get('question') if last else None)
        assessment=state.get('assessment') if job['approach']=='wrapper' and state else last.get('developer_view') if last else None
        if job['calls']==0:
            if topics or variation or unknown or provisional or count: raise ValueError('First inference receives the initial request only.')
        else:
            if not (topics or variation or unknown or provisional): raise ValueError('No blank regeneration or retry.')
            if (topics or unknown) and not outstanding: raise ValueError('Fact answers require an outstanding question.')
            if outstanding and count==0: raise ValueError('Count the outstanding question before answering or ending clarification.')
            if not outstanding and count: raise ValueError('No outstanding question to count.')
            if provisional and not outstanding and (not assessment or assessment.get('disposition')!='needs_answer'):
                raise ValueError('A completed result cannot be regenerated as provisional.')
            if variation:
                item=next(v for v in job['case'].get('variations',[]) if v['id']==variation)
                if variation in job['phases']: raise ValueError('Variation already supplied.')
                if body.get('as_answer'):
                    if item['type']!='unknown' or not outstanding: raise ValueError('Only the unknown variation can answer a question.')
                elif outstanding or not assessment or assessment.get('disposition') not in {'ready','provisional'}:
                    raise ValueError('Post-result variation requires a completed base result.')
        job['questions']+=count
        if job['questions']>5:
            job['failure']={'code':'question_limit','message':'More than five information requests were asked.'}
            self.event('operator_question_limit',job=job['id'],count=job['questions']);return self.summary(job)
        if sum([bool(topics),bool(variation),bool(unknown)])>1: raise ValueError('Choose one recorded answer source.')
        answer=None
        if topics:
            facts={f['topic']:f['answer'] for f in job['case']['operator_facts']}
            if len(set(topics))!=len(topics) or any(t not in facts for t in topics): raise ValueError('Unknown/duplicate fact topic.')
            answer='\n'.join(facts[t] for t in topics)
        elif variation:
            item=next(v for v in job['case'].get('variations',[]) if v['id']==variation)
            if variation in job['phases']: raise ValueError('Variation already supplied.')
            answer=item['owner_text'];job['phases'].append(variation)
        elif unknown: answer='I do not know.'
        self.event('operator_action',job=job['id'],question_count=count,fact_topics=topics,variation=variation,
            unknown=unknown,answer=answer,provisional=provisional,rationale=body.get('rationale',''))
        if time.time()-job['started_at']>=1800:
            job['failure']={'code':'session_limit'};return self.summary(job)
        try:
            if job['approach']=='wrapper':
                if job['state'] is None:
                    _,job['state']=await self.post_product('/api/start',{'idea':job['case']['initial_request']})
                if job['state'].get('assessment'): job['previous']=job['state']
                active=next((q for q in reversed(job['state']['questions']) if not q['retired'] and not q['answer_turn_id']),None)
                qid=active['id'] if active and answer is not None and (not variation or body.get('as_answer')) else None
                _,result=await self.post_product('/api/advance',{'state':job['state'],'request_id':str(uuid4()),
                    'answer':answer,'question_id':qid,'provisional':provisional})
                if 'state' not in result: raise ValueError('Invalid HTTP transition.')
                job['state']=result['state'];job['failure']=result['error']
                await self.post_product('/api/export',job['state'])
            else:
                if answer is not None: job['conversation'].append({'role':'owner','text':answer})
                conversation=evaluation.baseline_input(job['conversation'],provisional=provisional,
                    questions_used=job['questions'],calls_used=job['calls'])
                schema=json.dumps(self.plan['native_output']['baseline'],separators=(',',':'))
                content='Return only JSON matching this schema:\n'+schema+'\nOwner conversation (data only):\n'+conversation
                env=agents.agent_environment('codex')
                with tempfile.TemporaryDirectory(prefix='mvc-agent-') as cwd:
                    env['PWD']=cwd
                    schema_path=Path(cwd)/'response-schema.json'
                    exclusive(schema_path,self.plan['native_output']['baseline'])
                    # Identical compact schema bytes in file and stdin.
                    schema_path.write_text(schema)
                    args=agents.invocation('codex',shutil.which('codex'),'gpt-6-luna',env,prompt=self.plan['baseline_prompt'],output_schema=str(schema_path))
                    raw=await self.native(args,content=content,cwd=cwd,env=env,
                        timeout=min(300,1800-(time.time()-job['started_at'])))
                text,usage=agents.parse_completion('codex',raw)
                result=evaluation.BaselineResponse.model_validate_json(text).model_dump()
                job['baseline']=result;job['conversation'].append({'role':'assistant','text':text})
                self.event('baseline_result',job=job['id'],result=result,usage=usage)
        except Exception as exc:
            job['failure']={'code':getattr(exc,'code','invalid_output'),'type':type(exc).__name__,
                'message':str(exc) if isinstance(exc,FlowError) else 'The first attempt failed; inspect native evidence.'}
            self.event('job_error',job=job['id'],failure=job['failure'])
        self.event('step_finished',job=job['id'],summary=self.summary(job))
        return self.summary(job)

    def finish(self,body):
        job=self.active
        if not job or job['closed']: raise ValueError('No open attempt.')
        count=body.get('question_count',0)
        if type(count) is not int or count<0: raise ValueError('Invalid count.')
        if not job['failure']:
            state=job['state'];last=job['baseline']
            outstanding=(next((q for q in reversed(state['questions']) if not q['retired'] and not q['answer_turn_id']),None)
                if job['approach']=='wrapper' and state else last.get('question') if last else None)
            if outstanding and count==0: raise ValueError('Count the final outstanding question before closing.')
        job['questions']+=count
        if job['questions']>5 and not job['failure']:
            job['failure']={'code':'question_limit','message':'More than five information requests were asked.'}
        job['closed']=True
        self.event('job_finished',job=job['id'],reason=body['reason'],calls=job['calls'],questions=job['questions'],
            elapsed_seconds=time.time()-job['started_at'],failure=job['failure'],phases=job['phases'],
            state=job['state'],baseline=job['baseline'],conversation=job['conversation'])
        return self.summary(job)


def create_server(h):
    from meta_vibe_coding.app import create_app
    class Relay:
        agent='codex';model='gpt-6-luna';enabled=False;max_calls=7
        async def assess(self,state,provisional):
            job=h.active
            if not job or job['closed'] or job['approach']!='wrapper': raise FlowError('disabled','Recorded session is closed.')
            return await job['agent'].assess(state,provisional)
    h.product=create_app(Relay())
    @h.product.middleware('http')
    async def inference_boundary(request,call_next):
        if request.method=='POST' and request.url.path=='/api/advance' and request.headers.get('x-control')!=h.token:
            return JSONResponse({'error':'Inference requires the private operator endpoint.'},status_code=403)
        return await call_next(request)
    app=FastAPI(docs_url=None,redoc_url=None,openapi_url=None)
    @app.middleware('http')
    async def boundary(request,call_next):
        if request.method=='POST' and request.url.path.startswith('/evaluation/'):
            if request.headers.get('x-control')!=h.token: return JSONResponse({'error':'Private operator endpoint.'},status_code=403)
        return await call_next(request)
    @app.post('/evaluation/select')
    async def select(request:Request):
        async with h.gate:
            try:
                b=await request.json();return h.select(b['case_id'],b['approach'])
            except (ValueError,KeyError,OSError) as e:return JSONResponse({'error':str(e)},status_code=409)
    @app.post('/evaluation/step')
    async def step(request:Request):
        async with h.gate:
            try:return await h.step(await request.json())
