"""Interactive private control client; each line is a human-selected action."""
import json,sys,urllib.request
from pathlib import Path
token=json.loads(Path('/tmp/mvc-comparison-v2/control.json').read_text())['token']
print('Operator ready; no inference until an explicit action line.',flush=True)
for line in sys.stdin:
    try:
        action=json.loads(line)
        if action['mode']=='exit':break
        mode=action['mode'];body=action.get('body',{})
        req=urllib.request.Request('http://127.0.0.1:8005/evaluation/'+mode,
            data=None if mode=='status' else json.dumps(body).encode(),
            headers={'Content-Type':'application/json','x-control':token})
        with urllib.request.urlopen(req,timeout=310) as response:r=json.load(response)
        if 'assessment' in r:
            a=r.pop('assessment');r.pop('facts',None)
            if a:r['result']={'disposition':a['disposition'],'recommendation':a['recommendation']['summary'],'open_decisions':[q['text'] for q in a['open_questions']]}
        if 'response' in r:
            b=r.pop('response')
            if b:r.update(question=b['question'],owner_view=b['owner_view'],disposition=b['developer_view']['disposition'])
        print(json.dumps(r,ensure_ascii=False),flush=True)
    except Exception as exc:print(json.dumps({'control_error':str(exc)}),flush=True)
